async () => {
  const servers = ['google.com', 'cloudflare.com', 'github.com'];
  const results = {};

  for (const server of servers) {
    try {
      // Using a Promise-based approach to execute shell commands
      const { exec } = require('child_process');
      const util = require('util');
      const execPromise = util.promisify(exec);

      // Ping each server 3 times
      const { stdout, stderr } = await execPromise(`ping -c 3 ${server}`);
      results[server] = stdout;
    } catch (error) {
      results[server] = `Error pinging ${server}: ${error.message}`;
    }
  }

  return results;
}
